/* Pre-auth landing homepage + login modal (legacy SimpleLanding/AuthModal parity).
 * The hero is always the dark cinematic treatment (video bg + scrim), in the Radar's green-black, regardless of theme;
 * the modal uses the D12 tokens so it adapts to light/dark. */

.landing {
  position: fixed;
  inset: 0;
  overflow: visible;
  color: #fff;
  font-family: var(--font-sans);
  /* cinematic near-black: a cool radial glow off the upper-right over a black base,
   * darkest at the left where the hero text sits (legacy hero treatment, sans video) */
  background:
    radial-gradient(120% 90% at 88% 8%, rgba(7, 38, 26, 0.85) 0%, rgba(3, 13, 8, 0) 55%),
    radial-gradient(90% 80% at 12% 100%, rgba(59, 130, 246, 0.08) 0%, rgba(0, 0, 0, 0) 60%),
    #060a12;
}
.landing-bar {
  position: absolute;
  inset-inline: 0;
  z-index: 2;
  pointer-events: none;
}
.landing-bar-top {
  top: 0;
  height: 10vh;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.85), transparent);
}
.landing-bar-bottom {
  bottom: 0;
  height: 12vh;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.75), transparent);
}

.landing-header {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px clamp(2rem, 6vw, 9rem) 0 clamp(3rem, 9vw, 14rem);
  animation: landing-in 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.05s both;
}
.landing-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.landing-logo-img {
  height: 32px;
  width: auto;
  flex: none;
  display: block;
}
.landing-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}
.landing-lang {
  display: inline-flex;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  padding: 2px;
  backdrop-filter: blur(6px);
}
.landing-lang button {
  font: inherit;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: rgba(255, 255, 255, 0.6);
  border: 0;
  background: transparent;
  padding: 5px 13px;
  border-radius: 999px;
  cursor: pointer;
  transition: 0.2s;
}
.landing-lang button.on {
  background: var(--accent-primary);
  color: var(--text-on-accent);
}
.landing-theme {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.72);
  cursor: pointer;
  backdrop-filter: blur(6px);
  font-size: 15px;
  display: grid;
  place-items: center;
}
.landing-theme:hover {
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
}

.landing-hero {
  position: relative;
  z-index: 10;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 clamp(2rem, 6vw, 9rem) 0 clamp(3rem, 9vw, 14rem);
  animation: landing-in 1s cubic-bezier(0.22, 1, 0.36, 1) 0.15s both;
}
.landing-title {
  margin: 0;
  font-size: clamp(40px, 6vw, 64px);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.01em;
  white-space: nowrap;
  animation: landing-wipe 1.1s cubic-bezier(0.22, 1, 0.36, 1) 0.25s both;
}
.landing-accent {
  width: max-content;
  margin-top: 2px;
  font-size: clamp(30px, 4.5vw, 52px);
  font-style: italic;
  font-weight: 300;
  line-height: 1.1;
  background: linear-gradient(135deg, #3b82f6 0%, #93c5fd 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.landing-body {
  margin: 18px 0 26px;
  max-width: 34rem;
  font-size: 17px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.72);
}
.landing-cta {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent-primary);
  color: var(--text-on-accent);
  border: 0;
  border-radius: 999px;
  padding: 13px 24px;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 0 28px rgba(59, 130, 246, 0.35);
  animation: landing-glow 3s ease-in-out infinite;
  transition: filter 0.15s;
}
.landing-cta:hover {
  filter: brightness(1.08);
}

@keyframes landing-in {
  from {
    opacity: 0;
    transform: translateY(16px);
    filter: blur(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}
@keyframes landing-wipe {
  from {
    clip-path: inset(110% 0 0 0);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}
@keyframes landing-glow {
  0%,
  100% {
    box-shadow: 0 0 28px rgba(59, 130, 246, 0.35);
  }
  50% {
    box-shadow: 0 0 52px rgba(59, 130, 246, 0.6), 0 0 90px rgba(59, 130, 246, 0.2);
  }
}

/* ---- Branded sign-in: the airline's photograph as a band, its wordmark over it, the headline on an overlapping card.
 * The photographs are wide (3:1) and modest in resolution, so a band keeps them near 1.3x at 1080p and the aircraft in frame;
 * full-bleed would stretch them about 2.2x and crop the subject. knowledge-base/features/tenant-branding.md ---- */
.landing--branded {
  --band-h: clamp(320px, 56vh, 640px);
  overflow-y: auto;
  overflow-x: hidden;
}
.landing-ambient {
  position: absolute;
  inset: -25%;
  z-index: 0;
  background-size: cover;
  background-position: var(--landing-focal, 50% 50%);
  /* blurred past recognition: a lower radius leaves the aircraft's dark underside and tails as stains on the page */
  filter: blur(160px) saturate(1.3);
  opacity: 0.46;
  pointer-events: none;
  animation: landing-ambient-in 1.8s ease-out both;
}
@keyframes landing-ambient-in {
  from {
    opacity: 0;
  }
}
.landing-band {
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: var(--band-h);
  z-index: 1;
  overflow: hidden;
  background: #0a0f1a;
  /* the photograph dissolves into the page background; ending on a flat colour would leave a visible seam */
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 56%, transparent 100%);
  mask-image: linear-gradient(to bottom, #000 0%, #000 56%, transparent 100%);
}
.landing-band img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: var(--landing-focal, 50% 50%);
  animation: landing-band-in 1.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.landing-band::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(2, 6, 4, 0.66) 0%, rgba(2, 6, 4, 0.2) 36%, rgba(2, 6, 4, 0) 54%);
}
.landing-wordmark {
  display: block;
  height: 32px;
  width: auto;
  max-width: 60vw;
  filter: drop-shadow(0 1px 10px rgba(0, 0, 0, 0.5));
}
.landing--branded .landing-hero {
  height: auto;
  max-width: 41rem;
  box-sizing: border-box;
  margin: calc(var(--band-h) - 136px) clamp(2rem, 6vw, 9rem) 96px clamp(3rem, 9vw, 14rem);
  padding: 32px 38px 36px;
  border-radius: 22px;
  background: rgba(3, 13, 8, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(16px) saturate(1.2);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
}
.landing--branded .landing-title {
  font-size: clamp(30px, 4.2vw, 50px);
}
.landing--branded .landing-accent {
  font-size: clamp(24px, 3.4vw, 40px);
}
.landing--branded .landing-body {
  margin: 14px 0 24px;
}
.landing-powered {
  position: absolute;
  z-index: 10;
  left: clamp(3rem, 9vw, 14rem);
  bottom: 22px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: 0.02em;
  color: rgba(255, 255, 255, 0.55);
}
.landing-powered img {
  height: 18px;
  width: auto;
  opacity: 0.85;
}
@keyframes landing-band-in {
  from {
    opacity: 0;
    transform: scale(1.04);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@media (max-width: 720px) {
  .landing--branded {
    --band-h: 38vh;
  }
  .landing--branded .landing-header {
    padding-inline: 16px;
  }
  .landing--branded .landing-hero {
    margin: calc(var(--band-h) - 120px) 16px 88px;
    padding: 24px 22px 26px;
    border-radius: 18px;
  }
  .landing--branded .landing-title {
    white-space: normal;
  }
  .landing-powered {
    left: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .landing-band img,
  .landing-ambient {
    animation: none;
  }
}

/* ---- Light theme (html[data-theme="light"], the console's tokens). The photograph, the ambient wash and the wordmark follow
 * the theme: the white wordmark stays on the dark page and the airline's own colours go on the light one. ---- */
html[data-theme="light"] .landing {
  color: var(--text-primary);
  background: linear-gradient(180deg, #dcefe3 0%, #eef6f1 52%, #f9fcfa 100%);
}
html[data-theme="light"] .landing-bar {
  display: none;
}
html[data-theme="light"] .landing-ambient {
  opacity: 0.42;
  filter: blur(160px) saturate(1.2);
}
html[data-theme="light"] .landing-band::after {
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.78) 0%, rgba(255, 255, 255, 0.22) 36%, rgba(255, 255, 255, 0) 54%);
}
html[data-theme="light"] .landing-wordmark {
  filter: none;
}
html[data-theme="light"] .landing-lang {
  border-color: rgba(15, 23, 42, 0.16);
  background: rgba(255, 255, 255, 0.72);
}
html[data-theme="light"] .landing-lang button {
  color: rgba(26, 29, 41, 0.62);
}
html[data-theme="light"] .landing-lang button.on {
  color: #fff;
}
html[data-theme="light"] .landing-theme {
  border-color: rgba(15, 23, 42, 0.16);
  background: rgba(255, 255, 255, 0.72);
  color: var(--text-secondary);
}
html[data-theme="light"] .landing-theme:hover {
  background: #fff;
  color: var(--text-primary);
}
html[data-theme="light"] .landing-body {
  color: var(--text-secondary);
}
html[data-theme="light"] .landing-cta {
  box-shadow: 0 8px 24px rgba(8, 122, 63, 0.3);
  animation: none;
}
html[data-theme="light"] .landing--branded .landing-hero {
  background: rgba(255, 255, 255, 0.82);
  border-color: rgba(15, 23, 42, 0.1);
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
}
html[data-theme="light"] .landing-powered {
  color: rgba(26, 29, 41, 0.62);
}

/* ---- Login modal ---- */
.auth-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(4px);
  animation: auth-fade 0.15s ease-out;
}
.auth-modal {
  width: min(440px, 100%);
  box-sizing: border-box;
  background: var(--surface-card);
  border: 1px solid var(--border-primary);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  padding: 22px 24px 24px;
  color: var(--text-primary);
  animation: auth-pop 0.16s cubic-bezier(0.22, 1, 0.36, 1);
}
.auth-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}
.auth-head h2 {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
}
.auth-x {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  font-size: 14px;
}
.auth-x:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}
.auth-form {
  display: flex;
  flex-direction: column;
}
.auth-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}
.auth-field > span {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-secondary);
}
.auth-field input {
  width: 100%;
  box-sizing: border-box;
}
.auth-pw {
  position: relative;
  display: block;
}
.auth-pw input {
  padding-right: 38px;
}
.auth-eye {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  display: grid;
  place-items: center;
  padding: 4px;
}
.auth-eye:hover {
  color: var(--text-primary);
}
.auth-forgot {
  align-self: flex-start;
  border: 0;
  background: transparent;
  color: var(--accent-info);
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
  padding: 0;
  margin-bottom: 6px;
}
.auth-forgot:hover {
  text-decoration: underline;
}
.auth-info {
  font-size: 12px;
  color: var(--text-tertiary);
  margin-bottom: 8px;
}
.auth-form .pill.err {
  margin-bottom: 8px;
}
.auth-submit {
  margin-top: 6px;
  width: 100%;
  background: var(--accent-primary);
  color: var(--text-on-accent);
  border: 0;
  border-radius: 8px;
  padding: 11px;
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}
.auth-submit:hover {
  background: var(--accent-primary-hover);
}
.auth-submit:disabled {
  opacity: 0.7;
  cursor: default;
}

/* T7.1 federated login — rendered only when the tenant configured an IdP. Deliberately SECONDARY to the
   password form above it: SSO is an additional way in, not a replacement, and a tenant mid-rollout still
   has password users. */
.auth-sso {
  margin-top: 18px;
}
.auth-sso-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  color: var(--text-muted, #7a869a);
  font-size: 12px;
}
.auth-sso-divider::before,
.auth-sso-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border-subtle, #e2e6ec);
}
.auth-sso-button {
  display: block;
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 8px;
  padding: 11px;
  border: 1px solid var(--border-subtle, #e2e6ec);
  border-radius: 8px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s;
}
.auth-sso-button:hover {
  background: var(--surface-hover, #f4f6f9);
}
.auth-sso-note {
  margin-top: 4px;
  color: var(--text-muted, #7a869a);
  font-size: 11.5px;
  text-align: center;
}

@keyframes auth-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes auth-pop {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

